function ActivityHalloweenQuestNode:EntryOnClickHandler()
    local vo = self._activityDojo.unlock[1]
    local isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
    if not isUnlock then
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        GameUtils.Toast(err)
        return
    end
    
    HalloweenUtils.OpenUIJackpotDungoenMainDialog(self._activityDojo.id, self._activityDojo.prefab, { { id = Constants.UITypeIds.UIActivityMainDialog } })
end
