function ActivityHalloweenQuestNode:RefreshUI(activityDojo)
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(activityDojo.startTime, activityDojo.endTime))
    CfUtils.FillText(self.TxtContent, activityDojo.detail)
    CfUtils.FillText(self.BtnTxtTime, localize("距离结束:_time_", {_time_ = ActivityUtils.ConventLeftTimeText(activityDojo.endTime)}))

